using System;
using System.Linq;
using AICad.Contracts;
using Autodesk.AutoCAD.DatabaseServices;
using Autodesk.AutoCAD.Colors;
namespace AICad.Bridge;
internal static class NativeLayerStandards {
 internal static bool Same(LayerTableRecord a,LayerTableRecord b,Transaction at,Transaction bt){var al=(LinetypeTableRecord)at.GetObject(a.LinetypeObjectId,OpenMode.ForRead);var bl=(LinetypeTableRecord)bt.GetObject(b.LinetypeObjectId,OpenMode.ForRead);return a.Color.ColorMethod==b.Color.ColorMethod&&a.Color.ColorValue.ToArgb()==b.Color.ColorValue.ToArgb()&&a.LineWeight==b.LineWeight&&a.IsPlottable==b.IsPlottable&&al.NumDashes==bl.NumDashes&&Math.Abs(al.PatternLength-bl.PatternLength)<1e-6&&Enumerable.Range(0,al.NumDashes).All(i=>Math.Abs(al.DashLengthAt(i)-bl.DashLengthAt(i))<1e-6);}
 internal static void Resources(TemplateProfile template,Database db,Transaction tx){var layers=(LayerTable)tx.GetObject(db.LayerTableId,OpenMode.ForRead);foreach(var a in template.Layers){var appearance=a.Appearance;ObjectId lt=ObjectId.Null;if(appearance!=null){var types=(LinetypeTable)tx.GetObject(db.LinetypeTableId,OpenMode.ForRead);if(!types.Has(appearance.LineType)){if(appearance.SourceHash=="")throw new CadException("MISSING_LINETYPE",appearance.LineType);var source=new NativeBlockSource{FileHash=appearance.SourceHash};using var src=new Database(false,true);if(AICad.Contracts.Json.FileHash(NativeLibraryAssets.PathFor(source))!=appearance.SourceHash)throw new CadException("RESOURCE_CHANGED","Nguồn layer đã thay đổi.");src.ReadDwgFile(NativeLibraryAssets.PathFor(source),FileOpenMode.OpenForReadAndAllShare,true,"");src.CloseInput(true);using var read=src.TransactionManager.StartOpenCloseTransaction();var slt=(LinetypeTable)read.GetObject(src.LinetypeTableId,OpenMode.ForRead);if(!slt.Has(appearance.LineType))throw new CadException("MISSING_LINETYPE",appearance.LineType);src.WblockCloneObjects(new ObjectIdCollection(new[]{slt[appearance.LineType]}),db.LinetypeTableId,new IdMapping(),DuplicateRecordCloning.Ignore,false);}lt=types[appearance.LineType];if(appearance.Dashes!=null){var record=(LinetypeTableRecord)tx.GetObject(lt,OpenMode.ForRead);if(record.NumDashes!=appearance.Dashes.Count||Math.Abs(record.PatternLength-(appearance.PatternLength??0))>1e-6||Enumerable.Range(0,record.NumDashes).Any(i=>Math.Abs(record.DashLengthAt(i)-appearance.Dashes[i])>1e-6))throw new CadException("LINETYPE_CONFLICT",appearance.LineType);}}
 var color=appearance?.Rgb is int rgb?Color.FromRgb((byte)(rgb>>16),(byte)(rgb>>8),(byte)rgb):Color.FromColorIndex(ColorMethod.ByAci,a.Color);
 if(layers.Has(a.Name)){var old=(LayerTableRecord)tx.GetObject(layers[a.Name],OpenMode.ForRead);if(old.IsLocked||old.IsOff||old.IsFrozen||old.Color.ColorMethod!=color.ColorMethod||old.Color.ColorValue.ToArgb()!=color.ColorValue.ToArgb()||appearance!=null&&(old.LineWeight!=(LineWeight)appearance.LineWeight||old.IsPlottable!=appearance.Plottable||old.LinetypeObjectId!=lt))throw new CadException("LAYER_CONFLICT","Layer đích khác bộ chuẩn: "+a.Name);}else{layers.UpgradeOpen();var layer=new LayerTableRecord{Name=a.Name,Color=color};if(appearance!=null){layer.LinetypeObjectId=lt;layer.LineWeight=(LineWeight)appearance.LineWeight;layer.IsPlottable=appearance.Plottable;}layers.Add(layer);tx.AddNewlyCreatedDBObject(layer,true);}}}
 internal static void RestoreLayers(Database source,Transaction read,Database target,Transaction tx,IdMapping mapping){var table=(LayerTable)tx.GetObject(target.LayerTableId,OpenMode.ForRead);var replacements=new System.Collections.Generic.Dictionary<ObjectId,ObjectId>();foreach(IdPair pair in mapping){if(pair.Key.ObjectClass.Name!="AcDbLayerTableRecord"||pair.Value.IsNull)continue;var original=(LayerTableRecord)read.GetObject(pair.Key,OpenMode.ForRead);var cloned=(LayerTableRecord)tx.GetObject(pair.Value,OpenMode.ForWrite);if(table.Has(original.Name)&&table[original.Name]!=pair.Value){var existing=(LayerTableRecord)tx.GetObject(table[original.Name],OpenMode.ForRead);if(existing.IsLocked||existing.IsOff||existing.IsFrozen||!Same(original,existing,read,tx))throw new CadException("LAYER_CONFLICT","Layer nội bộ block khác chuẩn DWG đích: "+original.Name);replacements[pair.Value]=existing.ObjectId;}else if(cloned.Name!=original.Name)cloned.Name=original.Name;}
 foreach(IdPair pair in mapping)if(!pair.Value.IsNull&&pair.Value.ObjectClass.IsDerivedFrom(Autodesk.AutoCAD.Runtime.RXObject.GetClass(typeof(Entity)))){var e=(Entity)tx.GetObject(pair.Value,OpenMode.ForWrite);if(replacements.TryGetValue(e.LayerId,out var layer))e.LayerId=layer;}
 }
}
